<template>
 <el-drawer title="供应商拒收收回入库详情" :visible.sync="visible" size="94%" append-to-body>
  <div v-loading="loading" class="reclaim-detail">
   <el-alert v-if="error" :title="error" type="error" :closable="false"/>
   <template v-if="detail"><header><div><h2>{{detail.reclaim_sn}}</h2><p>{{states[detail.state]}} · {{dispatch[detail.dispatch_state]||detail.dispatch_state}}</p></div><el-button size="small" @click="show(detail.id)">刷新收回进度</el-button></header>
    <el-alert v-if="detail.last_error" :title="detail.last_error" type="warning" :closable="false"/>
    <el-alert v-if="detail.receipt_final&&detail.accepted_quantity<detail.quantity&&detail.state==='ACTIVE'" title="仓库已最终结束本次收货，尚有计划未收回。按实际已收数量入账，核对后可停止剩余收回计划。" type="warning" :closable="false"/>
    <div class="metrics"><article><span>计划收回</span><strong>{{units('quantity')}}</strong></article><article><span>仓库实收</span><strong>{{units('accepted_quantity')}}</strong></article><article><span>库存已恢复</span><strong>{{units('posted_quantity')}}</strong></article><article><span>已实收待入账</span><strong>{{units('pending')}}</strong></article></div>
    <el-descriptions border :column="3" size="small"><el-descriptions-item label="收回虚仓">{{detail.store_code}}</el-descriptions-item><el-descriptions-item label="入库方式">{{Number(detail.inbound_mode)===1?'奇门QTRK实收回传':'自动虚拟入库'}}</el-descriptions-item><el-descriptions-item label="仓库原单号">{{detail.external_order||'尚未受理'}}</el-descriptions-item><el-descriptions-item label="供应商退回快递">{{carrierInfo(detail).standard_name||'标准身份待核实'}}</el-descriptions-item><el-descriptions-item label="WMS 入库目标编码">{{detail.carrier_code||'尚未确认'}}</el-descriptions-item><el-descriptions-item label="供应商退回运单">{{detail.waybill}}</el-descriptions-item><el-descriptions-item label="收回原因">{{detail.reason}}</el-descriptions-item></el-descriptions>
    <el-alert v-if="!detail.standard_id" title="原始退回物流已保存，标准快递尚未核实。确认标准身份和收货能力后才能审核下发。" type="warning" :closable="false"/>
    <el-descriptions v-if="detail.raw_carrier_code||detail.raw_carrier_name" border :column="2" size="small"><el-descriptions-item label="供应商原始编码">{{detail.raw_carrier_code||'未提供'}}</el-descriptions-item><el-descriptions-item label="供应商原始名称">{{detail.raw_carrier_name||'未提供'}}</el-descriptions-item></el-descriptions>
    <el-form v-if="detail.state==='DRAFT'&&!detail.standard_id" label-width="150px"><el-form-item label="凭证确认标准快递"><purchase-return-carrier-select v-model="confirmedStandard" :purchase-id="detail.purchase_id" :active="visible"/></el-form-item><el-form-item label="快递核对凭证"><el-input v-model="carrierEvidence" type="textarea" maxlength="1000" placeholder="填写供应商物流凭证及标准快递核对依据"/></el-form-item></el-form>
    <div class="toolbar"><el-button v-if="detail.state==='DRAFT'" v-hasPermi="['warehouse:purchaseReturn:reclaimApprove']" type="primary" size="small" :loading="busy" @click="act('approve')">审核并自动收回入库</el-button><el-button v-if="['ACTIVE','CANCELING'].includes(detail.state)&&detail.last_error" v-hasPermi="['warehouse:purchaseReturn:reclaimRetry']" size="small" :loading="busy" @click="act('retry')">重试未完成入库步骤</el-button><el-button v-if="detail.state!=='DRAFT'&&Number(detail.inbound_mode)===1" v-hasPermi="['warehouse:purchaseReturn:queryWarehouse']" size="small" :loading="busy" @click="act('query')">查询原收回仓单</el-button><el-button v-if="!['CANCELED','COMPLETED'].includes(detail.state)" v-hasPermi="['warehouse:purchaseReturn:reclaimRetry']" size="small" :disabled="!!detail.receipt_review_pending" :loading="busy" @click="act('cancel')">{{detail.state==='DRAFT'?'取消收回草稿':'停止剩余收回'}}</el-button></div>
    <el-tabs v-model="tab"><el-tab-pane label="计划与实际实收" name="lines"><el-table :data="detail.lines" size="small"><el-table-column label="原拒收来源 / 仓库执行" min-width="250"><template slot-scope="{row}"><template v-if="row.supplier_source_id">拒收来源 #{{row.supplier_source_id}}<div class="muted">{{row.execution_sn}} · 原收货凭证 #{{row.supplier_receipt_id}}</div><div class="muted">{{row.supplier_parcels||'尚未关联具体包裹'}}</div></template><span v-else>见原退仓商品</span></template></el-table-column><el-table-column label="原商品 / 批次 / 计划质量" min-width="270"><template slot-scope="{row}">{{row.goods_name}}<div class="muted">{{row.sku_sn}} · {{row.batch_code}} · {{row.inventory_type==='ZP'?'正品':'次品'}}</div></template></el-table-column><el-table-column label="计划 / 实收 / 入账" min-width="180"><template slot-scope="{row}">{{row.quantity}} / {{row.accepted_quantity}} / {{row.posted_quantity}} {{row.stock_unit}}</template></el-table-column><el-table-column label="原采购单价"><template slot-scope="{row}">¥{{Number(row.purchase_price).toFixed(2)}}</template></el-table-column></el-table><h3>仓库实际质检与入账来源</h3><el-table :data="detail.receipt_lines||[]" size="small" empty-text="尚未收到有效的仓库实收"><el-table-column prop="sku_sn" label="实际SKU"/><el-table-column prop="batch_code" label="原批次"/><el-table-column label="实际质量"><template slot-scope="{row}">{{row.inventory_type==='ZP'?'正品':'次品'}}</template></el-table-column><el-table-column label="实收数量"><template slot-scope="{row}">{{row.quantity}} {{row.stock_unit}}</template></el-table-column><el-table-column label="库存来源 / 入账"><template slot-scope="{row}">{{row.origin_relation}}<div>{{row.posted?'已入账':'待入账'}}</div></template></el-table-column></el-table></el-tab-pane>
    <el-tab-pane label="实收与入账事件" name="events"><el-table :data="detail.events" size="small"><el-table-column prop="message_id" label="原实收消息"/><el-table-column prop="quantity" label="本次实收"/><el-table-column label="入账结果"><template slot-scope="{row}">{{row.state==='POSTED'?'入账成功':row.state==='FAILED'?'入账失败':'等待入账'}}<div class="danger">{{row.last_error}}</div></template></el-table-column><el-table-column prop="create_time" label="时间"/></el-table></el-tab-pane>
    <el-tab-pane label="仓库交互" name="logs" lazy><warehouse-interactions v-if="tab==='logs'&&Number(detail.inbound_mode)===1" :sn="detail.reclaim_sn"/><el-empty v-else description="虚拟收回没有外部仓库交互"/></el-tab-pane></el-tabs>
   </template>
  </div>
 </el-drawer>
</template>
<script>
import PurchaseReturnCarrierSelect from './PurchaseReturnCarrierSelect'
import { carrierInfo } from '@/utils/carrierPresentation'
import {reclaimDetail,reclaimAction} from '@/api/purchase/returns'
import WarehouseInteractions from '../order/ReturnInteractionPanel'
export default{components:{WarehouseInteractions,PurchaseReturnCarrierSelect},data:()=>({visible:false,loading:false,busy:false,detail:null,confirmedStandard:'',carrierEvidence:'',error:'',tab:'lines',sequence:0,states:{DRAFT:'待审核',ACTIVE:'收回执行中',CANCELING:'停止剩余收回待确认',CANCELED:'剩余已停止',COMPLETED:'全部收回入账'},dispatch:{UNSENT:'尚未下发',PENDING:'等待下发',SENDING:'下发结果待确认',UNKNOWN:'受理结果待确认',ACCEPTED:'仓库已受理',FAILED:'下发失败',CANCELED:'仓库已停止',VIRTUAL:'自动虚拟入库'}}),beforeDestroy(){this.sequence++},methods:{carrierInfo,async show(id){const seq=++this.sequence;this.visible=true;this.loading=true;this.error='';try{const d=(await reclaimDetail(id)).data;if(seq===this.sequence){this.detail=d;this.confirmedStandard='';this.carrierEvidence='';this.$emit('changed')}}catch(e){if(seq===this.sequence)this.error=e.message||'收回详情加载失败'}finally{if(seq===this.sequence)this.loading=false}},units(key){const result={};for(const l of this.detail.lines||[]){const q=key==='pending'?Number(l.accepted_quantity)-Number(l.posted_quantity):Number(l[key]);result[l.stock_unit]=(result[l.stock_unit]||0)+q}return Object.keys(result).filter(k=>result[k]>0).map(k=>result[k]+' '+k).join(' + ')||'0'},async act(action){if(this.busy)return;const body={control_version:this.detail.control_version};try{if(action==='approve'&&!this.detail.standard_id){if(!this.confirmedStandard||!this.carrierEvidence.trim())return this.$message.warning('请确认标准快递并填写核对凭证');Object.assign(body,{standard_id:this.confirmedStandard,carrier_evidence:this.carrierEvidence})}if(action==='approve')await this.$confirm('审核后自动下发原仓库，按实际实收恢复库存，原出库记录保留。确认审核？','审核收回入库');if(action==='cancel')body.reason=(await this.$prompt('请填写取消或停止剩余收回的依据。已实收入账部分保留。','停止收回',{inputType:'textarea',inputValidator:v=>!!v&&v.trim().length>=2||'请填写至少2字依据'})).value;this.busy=true;await reclaimAction(this.detail.id,action,body);await this.show(this.detail.id)}catch(e){if(e!=='cancel'&&e!=='close')this.$message.error(e.message||'操作未确认，请刷新原单')}finally{this.busy=false}}}}
</script>
<style scoped>.reclaim-detail{padding:0 24px 35px}header,.toolbar{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:18px 0}.toolbar{justify-content:flex-start;flex-wrap:wrap}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0}.metrics article{padding:18px;background:#f4f7fc;border-radius:8px}.metrics span{display:block;color:#7a899d;font-size:12px}.metrics strong{display:block;font-size:25px;margin-top:8px}.muted{font-size:12px;color:#7a899d;line-height:1.8;overflow-wrap:anywhere}.danger{color:#c74545}.el-tabs{margin-top:20px}</style>
